    static {
        var builder = new ModConfigSpec.Builder();
        for (int i = 0; i < 2; i++) {
            builder.push(i == 0 ? "crasher" : "thrasher");
            HEALTH[i] = builder.defineInRange("maxHealth", i == 0 ? 82.0 : 45.0, 1, 1000000);
